import json


def parse_script(text: str) -> dict:
    """
    Parse a dialogue script into a structured graph with nodes and edges.

    Returns a dict with keys "nodes" and "edges".
    """
    nodes = []
    edges = []
    node_ids = set()

    # Split by section headers — a newline followed by '[' starts a new section
    sections = re.split(r'\n(?=\[)', text.strip())

    for section in sections:
        section = section.strip()
        if not section:
            continue

        header_match = re.match(r'\[([^\]]+)\]', section)
        if not header_match:
            continue

        section_id = header_match.group(1)
        node_ids.add(section_id)

        content = section[header_match.end():].strip()
        lines = [l.strip() for l in content.split('\n') if l.strip()]
        if not lines:
            continue

        # A section is a "choice" when its first line starts with a number + dot
        is_choice = bool(re.match(r'^\d+\.', lines[0]))

        if is_choice:
            nodes.append({
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            })
            for line in lines:
                m = re.match(r'^\d+\.\s+(.*?)\s*->\s*(\S+)$', line)
                if m:
                    edges.append({
                        "from": section_id,
                        "to": m.group(2).strip(),
                        "text": m.group(1).strip()
                    })
        else:
            for line in lines:
                m = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(\S+)$', line)
                if m:
                    nodes.append({
                        "id": section_id,
                        "text": m.group(2).strip(),
                        "speaker": m.group(1).strip(),
                        "type": "line"
                    })
                    edges.append({
                        "from": section_id,
                        "to": m.group(3).strip(),
                        "text": ""
                    })
                    break

    # Add any referenced targets that don't have their own section (e.g. "End")
    all_targets = {e["to"] for e in edges}
    for target in sorted(all_targets - node_ids):
        nodes.append({
            "id": target,
            "text": "",
            "speaker": "",
            "type": "line"
        })
        node_ids.add(target)

    return {"nodes": nodes, "edges": edges}


def validate_graph(graph: dict) -> list[str]:
    """Validate the graph and return a list of issues (empty = valid)."""
    issues = []
    nodes = graph["nodes"]
    edges = graph["edges"]

    node_ids = {n["id"] for n in nodes}
    node_by_id = {n["id"]: n for n in nodes}

    if not nodes:
        issues.append("Graph has no nodes")
        return issues

    first_id = nodes[0]["id"]

    # (1) All nodes must be reachable from the first node
    adj = {nid: [] for nid in node_ids}
    for e in edges:
        adj[e["from"]].append(e["to"])

    visited = set()
    stack = [first_id]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in visited:
                stack.append(nxt)

    unreachable = node_ids - visited
    if unreachable:
        issues.append(f"Unreachable nodes: {', '.join(sorted(unreachable))}")

    # (2) All edge targets must exist (terminal / last nodes are exempt — they
    #     just need to exist as a node, which we already guarantee above).
    for e in edges:
        if e["to"] not in node_ids:
            issues.append(f"Edge {e['from']} -> {e['to']}: target does not exist")

    return issues


def generate_dot(graph: dict) -> str:
    """Generate a Graphviz DOT representation of the dialogue graph."""
    lines = ["digraph Dialogue {",
             "    rankdir=TB;",
             "    node [shape=box, style=filled];",
             ""]

    for n in graph["nodes"]:
        nid = n["id"]
        if n["type"] == "choice":
            label = nid
            shape = 'shape=diamond, fillcolor="#fdf6e3"'
        elif nid == "End":
            shape = 'shape=doublecircle, fillcolor="#d5f5e3"'
        else:
            speaker = n.get("speaker", "")
            text = n.get("text", "")
            label = f"{speaker}: {text}" if speaker else nid
            label = label.replace('"', '\\"')
            shape = 'fillcolor="#eaf2f8"'
        lines.append(f'    "{nid}" [{shape}, label="{label}"];')

    lines.append("")
    for e in graph["edges"]:
        src = e["from"]
        dst = e["to"]
        label = e["text"].replace('"', '\\"') if e["text"] else ""
        if label:
            lines.append(f'    "{src}" -> "{dst}" [label="{label}"];')
        else:
            lines.append(f'    "{src}" -> "{dst}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    with open("/app/script.txt", "r") as f:
        script_text = f.read()

    graph = parse_script(script_text)

    # Validate
    issues = validate_graph(graph)
    if issues:
        print("VALIDATION ISSUES:")
        for issue in issues:
            print(f"  - {issue}")
    else:
        print("Validation passed.")

    # Write JSON
    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    # Write DOT
    dot = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot)

    print(f"Nodes: {len(graph['nodes'])}, Edges: {len(graph['edges'])}")
    print("Output: /app/dialogue.json, /app/dialogue.dot")", "path": "/app/solution.py"}: Editing /app/solution.py

